let effect;

async function init() {
	// you can put underscores in numbers to make them more readable
	effect = new Effect(250_000);

	effect.image(await urlToImageData("testImage.jpg"), 0.75, 0.0);

	regl.frame(update);

	// link to the html ui
	const uiContainer = document.getElementById("uiContainer");
	const timeoutHandle = setTimeout(() => effect.explode(), 1000);
	addEventListener("mousemove", (event) => {
		uiContainer.style.visibility = "visible"
		clearTimeout(timeoutHandle);
	});
	const crazyInput = document.getElementById("crazyInput");
	const imageInput = document.getElementById("imageInput");
	const explodeButton = document.getElementById("explodeButton");
	const assembleButton = document.getElementById("assembleButton");
	imageInput.addEventListener("change", async () => {
		const files = imageInput.files;
		if (files.length === 0) return;
		effect.createBuffers(crazyInput.checked ? 6_250_000 : 250_000);
		effect.image(await blobToImageData(files[0]), 0.75, crazyInput.checked ? 1.0 : 5.0);
	});
	explodeButton.addEventListener("click", () => effect.explode());
	assembleButton.addEventListener("click", () => effect.assemble());
}

function update() {
	regl.clear({
		color: [1, 1, 1, 1]
	});

	effect.draw();
}

async function urlToImageData(url) {
	let response = await fetch(url, {
		method: "GET"
	});
	const fileBlob = await response.blob();
	return blobToImageData(fileBlob);
}

async function blobToImageData(fileBlob) {
	const bitmap = await createImageBitmap(fileBlob);

	const canvas = document.createElement("canvas");
	canvas.width = bitmap.width;
	canvas.height = bitmap.height;
	const ctx = canvas.getContext('2d');

	ctx.drawImage(bitmap, 0, 0);
	bitmap.close();

	return ctx.getImageData(0, 0, canvas.width, canvas.height);
}

