// === Tab: effect.js ===
const regl = createREGL();

class Effect {
	constructor(maxBlobs = 800_000) {
		this.createBuffers(maxBlobs);

		this.positionQueue = [];
		this.colorQueue = [];
		this.radiusQueue = [];
		this.accelerationQueue = [];

		this.blobCount = 0;
		this.explodedCount = 0;
		this.explodeTime = null;
	}

	createBuffers(maxBlobs) {
		if (maxBlobs === this.bufferSize) return;
		this.positionBuffer = regl.buffer({
			length: 8 * maxBlobs,
			type: "float",
			usage: "dynamic"
		});
		this.colorBuffer = regl.buffer({
			length: 12 * maxBlobs,
			type: "float",
			usage: "dynamic"
		});
		this.radiusBuffer = regl.buffer({
			length: 4 * maxBlobs,
			type: "float",
			usage: "dynamic"
		});
		this.initialVelocityBuffer = regl.buffer({
			length: 8 * maxBlobs,
			type: "float",
			usage: "dynamic"
		});
		this.accelerationBuffer = regl.buffer({
			length: 8 * maxBlobs,
			type: "float",
			usage: "dynamic"
		});
		this.bufferSize = maxBlobs;
	}

	explode() {
		const explodingCount = this.blobCount - this.explodedCount;
		const initalVelocities = [];

		for (let i = 0; i < explodingCount; i++) {
			initalVelocities.push([random(-90, 90), random(-90, 90)]);
		}

		this.initialVelocityBuffer.subdata(initalVelocities, this.explodedCount * 8);

		this.explodeTime = regl.now();
	}

	assemble() {
		this.explodeTime = null;
	}

	image(imageData, imageScale, blobRadius) {
		this.clear();
		this.explodeTime = null;

		const imageScreenRatio = Math.max(
			imageData.width / window.innerWidth,
			imageData.height / window.innerHeight) / imageScale;
		const areaWidth = Math.floor(imageData.width / imageScreenRatio);
		const areaHeight = Math.floor(imageData.height / imageScreenRatio);
		const imageRadius = Math.hypot(areaWidth, areaHeight) / 2 + 10;

		for (let i = 0; i < 4; i++) {
			this.queueImageChannel({
				offsetX: random(-20, 20),
				offsetY: random(-20, 20),
				angle: random(0, Math.PI * 2),
				channel: i,
				imageData,
				imageRadius,
				imageScreenRatio,
				areaWidth,
				areaHeight,
				blobRadius
			});
		}

		this.bufferQueues();
	}

	queueImageChannel({
		offsetX,
		offsetY,
		angle,
		channel,
		imageData,
		imageRadius,
		imageScreenRatio,
		areaWidth,
		areaHeight,
		blobRadius
	}) {
		const iosScalar = isIOS() ? 2.0 : 1.0;

		const rowCoords = [],
			colCoords = [];
		for (let u = -imageRadius; u < imageRadius; u += blobRadius * random(1.5, 1.7)) {
			rowCoords.push(u);
		}
		for (let v = -imageRadius; v < imageRadius; v += blobRadius * random(1.5, 1.7)) {
			colCoords.push(v);
		}

		const
			cosAngle = Math.cos(angle),
			sinAngle = Math.sin(angle);
		for (let i = 0; i < rowCoords.length; i++) {
			const u = rowCoords[i];
			for (let j = 0; j < colCoords.length; j++) {
				const v = colCoords[j];
				const sampleX = cosAngle * u - sinAngle * v + offsetX;
				const sampleY = sinAngle * u + cosAngle * v + offsetY;
				const [r, g, b] = getImageData(imageData,
					(sampleX + areaWidth / 2) * imageScreenRatio,
					(sampleY + areaHeight / 2) * imageScreenRatio);

				const
					k = 255 - Math.max(r, g, b),
					c = (255 - r - k) / (255.000001 - k) * 255,
					m = (255 - g - k) / (255.000001 - k) * 255,
					y = (255 - b - k) / (255.000001 - k) * 255;

				const scale = Math.sqrt(([c, m, y, k])[channel] / 192.82);
				if (scale < 0.3) continue;

				const color = ([
					[0, 1, 1],
					[1, 0, 1],
					[1, 1, 0],
					[0.15, 0.15, 0.15]
				])[channel];

				const gravity = ([
					[40, 40],
					[-40, 40],
					[40, -40],
					[-40, -40]
				])[channel];

				this.queueBlob(
					[sampleX + random(-0.35, 0.35), sampleY + random(-0.35, 0.35)],
					color,
					blobRadius * scale * iosScalar,
					gravity);
			}
		}
	}

	queueBlob(position, color, radius, acceleration) {
		this.positionQueue.push(position);
		this.colorQueue.push(color);
		this.radiusQueue.push(radius);
		this.accelerationQueue.push(acceleration);
	}

	bufferQueues() {
		this.positionBuffer.subdata(this.positionQueue, this.blobCount * 8);
		this.colorBuffer.subdata(this.colorQueue, this.blobCount * 12);
		this.radiusBuffer.subdata(this.radiusQueue, this.blobCount * 4);
		this.accelerationBuffer.subdata(this.accelerationQueue, this.blobCount * 8);

		this.blobCount += this.positionQueue.length;
	}

	draw = regl({
		vert: `
		precision mediump float;

		attribute vec2 aPosition;
		attribute vec3 aColor;
		attribute float aRadius;
		attribute vec2 aInitialVelocity;
		attribute vec2 aAcceleration;

		uniform vec2 uScreenSize;
		uniform float uTime;

		varying vec3 vColor;

		void main() {
			vColor = aColor;

			vec2 velocity = aInitialVelocity + aAcceleration * uTime;
			vec2 position = aPosition + velocity * uTime;
			position *= vec2(2.0, -2.0) / uScreenSize;

			gl_Position = vec4(position, 0, 1);
			gl_PointSize = aRadius * 2.0;
		}`,

		frag: `
		precision lowp float;

		varying vec3 vColor;

		void main() {
			float centerDist = length(gl_PointCoord.xy - 0.5) * 2.0;
			if (centerDist > 1.0) discard;
			gl_FragColor = vec4(vColor + centerDist * centerDist * centerDist, 1.0);
		}`,

		attributes: {
			aPosition: regl.this("positionBuffer"),
			aColor: regl.this("colorBuffer"),
			aRadius: regl.this("radiusBuffer"),
			aInitialVelocity: regl.this("initialVelocityBuffer"),
			aAcceleration: regl.this("accelerationBuffer")
		},

		uniforms: {
			uScreenSize: () => {
				return [window.innerWidth, window.innerHeight];
			},
			uTime: ({
				time
			}) => {
				if (this.explodeTime === null) return 0;
				return time - this.explodeTime;
			}
		},

		primitive: "points",

		depth: {
			enable: false
		},

		blend: {
			enable: true,
			func: {
				srcRGB: 'zero',
				srcAlpha: 'one',
				dstRGB: 'src color',
				dstAlpha: 'one'
			},
			equation: {
				rgb: 'add',
				alpha: 'add'
			}
		},

		count: regl.this("blobCount")
	});

	clear() {
		this.blobCount = 0;
		this.positionQueue = [];
		this.colorQueue = [];
		this.radiusQueue = [];
		this.accelerationQueue = [];
	}

	destroy() {
		this.positionBuffer.destroy();
		this.colorsBuffer.destroy();
	}
}

function random(min, max) {
	return min + Math.random() * (max - min);
}

function getImageData(imageData, x, y) {
	if (x < 0 || x >= imageData.width ||
		y < 0 || y >= imageData.height) {
		return [255, 255, 255];
	}

	const index = (Math.floor(x) + Math.floor(y) * imageData.width) * 4;
	const
		r = imageData.data[index + 0],
		g = imageData.data[index + 1],
		b = imageData.data[index + 2],
		a = imageData.data[index + 3];

	// blend r, g and b to white with a
	return [
		(r * (a + 1) >> 8) - a + 255,
		(g * (a + 1) >> 8) - a + 255,
		(b * (a + 1) >> 8) - a + 255
	];
}

function isIOS() {
	return [
		'iPad Simulator',
		'iPhone Simulator',
		'iPod Simulator',
		'iPad',
		'iPhone',
		'iPod'
	].includes(navigator.platform)
}

// === Tab: poly.js ===
/*
* Safari and Edge polyfill for createImageBitmap
* https://developer.mozilla.org/en-US/docs/Web/API/WindowOrWorkerGlobalScope/createImageBitmap
*
* Support source image types Blob and ImageData.
*
* From: https://dev.to/nektro/createimagebitmap-polyfill-for-safari-and-edge-228
* Updated by Yoan Tournade <yoan@ytotech.com>
*/
if (!('createImageBitmap' in window)) {
	window.createImageBitmap = async function (data) {
		return new Promise((resolve, reject) => {
			let dataURL;
			if (data instanceof Blob) {
				dataURL = URL.createObjectURL(data);
			} else if (data instanceof ImageData) {
				var canvas = document.createElement('canvas');
				var ctx = canvas.getContext('2d');
				canvas.width = data.width;
				canvas.height = data.height;
				ctx.putImageData(data, 0, 0);
				dataURL = canvas.toDataURL();
			} else {
				throw new Error('createImageBitmap does not handle the provided image source type');
			}
			const img = document.createElement('img');
			img.close = () => { };
			img.addEventListener('load', function () {
				resolve(this);
			});
			img.src = dataURL;
		});
	};
}

